(* [comment removed for export] *)
Lemma bit_slot_nonH g b ai i : s_groups st !! b = Some (mkGhdr (Some g) ai) -> 0 <= i <= m_last_idx (MR st g) ->
  (Z.testbit (m_avail (MR st g)) i = true \/ Z.testbit (m_freed (MR st g)) i = true) ->
